/* ===================== BÀI 7 · CPU, bộ nhớ và bus ===================== */
/* ---- công cụ tương tác của bài: chép từ tools/author/nentang/w07.js bởi m02lib.write2 ---- */
/* Bài 7 · CPU đọc một ô nhớ qua bus (AMTS-FND-002-SIM07 CPU Register and Bus, bản cho Bài 7).
   NTE7: phần TÍNH (engine), hàm thuần, không đụng DOM; kiểm thử: node tests/nentang/test_m02.js (so với Python độc lập).
   makeNtBusRead: phần VẼ: chọn kiểu truy cập (nạp lệnh, MOVC, MOVX của 8051; đọc bộ nhớ 8086), nhập địa chỉ, chạy từng pha
   của chu kỳ đọc và xem giá trị trên cổng 2 (A15–A8), cổng 0 (AD7–AD0) / bus 8086, các tín hiệu ALE, PSEN, RD, M/IO.
   Nội dung bộ nhớ là GIẢ ĐỊNH của bài. Mô hình thứ tự sự kiện, không phải giản đồ thời gian chính xác (không có ns, setup/hold).
   Khóa hi8 = giá trị trên cổng 2, lo8 = giá trị trên cổng 0 (viết chữ thường để build.py không nhầm với biến của bài khác). */
const NTE7={
  /* bộ nhớ giả định: code = bộ nhớ chương trình 8051, xdata = RAM ngoài 8051, m86 = bộ nhớ 8086 (địa chỉ vật lý) */
  MEM:{code:{0:0x74,1:0x3C,2:0x90,3:0x01,4:0x00,256:0x3F,257:0x06,258:0x5B,259:0x4F},xdata:{256:0x5A,0x2A51:0xC3},m86:{0x12350:0x7E,0x20100:0x99,0xB8000:0x41}},
  /* đọc số hex: 2A51, 2A51H, 02A51H, 0x2A51, FFH; trả NaN nếu sai hoặc vượt max. Dùng bộ đọc chung NT.hexLit
     (courses/nentang/course.js) để mọi ô hex của khóa nhận cùng các cách viết. */
  hex(s,max){const r=NT.hexLit(s,true);return r.ok&&r.v<=max?r.v:NaN},
  /* địa chỉ vật lý 8086: segment × 16 + offset, giữ 20 bit (8086 chỉ có A19–A0 nên quay vòng về đầu bộ nhớ) */
  phys(seg,off){const s=seg*16+off;return{addr:s%0x100000,wrap:s>0xFFFFF}},
  /* một lần đọc của 8051. kind: "fetch" (nạp byte lệnh tại PC), "movc" (MOVC A,@A+DPTR), "movx" (MOVX A,@DPTR).
     Trả {addr, hi, lo, strobe, space, data (null nếu ô chưa có trong mô hình), phases} */
  read51(kind,addr,a){a=a||0;const ad=(kind==="movc"?addr+a:addr)&0xFFFF,space=kind==="movx"?"xdata":"code",strobe=kind==="movx"?"RD":"PSEN";
    const d=NTE7.MEM[space][ad],data=d===undefined?null:d,hi=ad>>8,lo=ad&255;
    const ph=[{t:"Đặt địa chỉ, ALE lên",ALE:1,PSEN:1,RD:1,hi8:hi,lo8:lo},{t:"ALE xuống: mạch chốt giữ A7–A0",ALE:0,PSEN:1,RD:1,hi8:hi,lo8:lo},
      {t:`${strobe} xuống: bộ nhớ đặt dữ liệu lên cổng 0`,ALE:0,PSEN:strobe==="PSEN"?0:1,RD:strobe==="RD"?0:1,hi8:hi,lo8:data},
      {t:`CPU chốt dữ liệu, ${strobe} lên`,ALE:0,PSEN:1,RD:1,hi8:hi,lo8:data}];
    return{addr:ad,hi,lo,strobe,space,data,phases:ph}},
  /* một lần đọc byte của 8086 ở chế độ tối thiểu, 4 trạng thái T1–T4 */
  read86(seg,off){const p=NTE7.phys(seg,off),d=NTE7.MEM.m86[p.addr],data=d===undefined?null:d;
    const ph=[{t:"T1: đặt địa chỉ 20 bit, ALE",ALE:1,RD:1,MIO:1,A:p.addr,D:null},{t:"T2: RD xuống",ALE:0,RD:0,MIO:1,A:null,D:null},
      {t:"T3: bộ nhớ đặt dữ liệu",ALE:0,RD:0,MIO:1,A:null,D:data},{t:"T4: CPU đã chốt dữ liệu, RD lên",ALE:0,RD:1,MIO:1,A:null,D:data}];
    return Object.assign(p,{data,phases:ph})}
};
function makeNtBusRead(el,cfg){
  cfg=cfg||{};const P="ntb-"+(cfg.id||"x");let k=0,cur=null;
  const H=(v,n)=>v==null?"?":v.toString(16).toUpperCase().padStart(n||2,"0")+"H";
  el.classList.add("nt7-bus");
  el.innerHTML=`<div class="nt7-row"><label>Kiểu truy cập<select id="${P}-k"><option value="fetch">8051: nạp byte lệnh (PSEN)</option><option value="movc">8051: MOVC A,@A+DPTR</option><option value="movx" selected>8051: MOVX A,@DPTR</option><option value="r86">8086: MOV AL,[BX] (DS)</option></select></label>
    <label id="${P}-la"><span id="${P}-lt">DPTR (hex)</span><input id="${P}-a" type="text" autocomplete="off" spellcheck="false" value="0100"></label>
    <label id="${P}-lx" hidden>A (hex, cho MOVC)<input id="${P}-x" type="text" autocomplete="off" spellcheck="false" value="00"></label>
    <label id="${P}-ls" hidden>DS (hex)<input id="${P}-s" type="text" autocomplete="off" spellcheck="false" value="1234"></label></div>
   <p class="nt-err" id="${P}-err" role="status" aria-live="polite"></p>
   <div class="nt7-ph"><button type="button" class="btn" id="${P}-prev">← Lùi</button><button type="button" class="btn pri" id="${P}-next">Bước tiếp →</button><button type="button" class="btn" id="${P}-all">Xem hết</button><span class="mt-k" id="${P}-st" role="status"></span></div>
   <div id="${P}-out" aria-live="polite"></div>
   <p class="mt-cap">Nội dung bộ nhớ là giả định của bài; ô chưa có trong mô hình hiện “?”. Mô hình chỉ cho thứ tự sự kiện của một lần đọc, không cho thời gian tính bằng ns.</p>`;
  const $=s=>el.querySelector("#"+P+"-"+s);
  function calc(){const kind=$("k").value,is86=kind==="r86";
    $("lx").hidden=kind!=="movc";$("ls").hidden=!is86;$("lt").textContent=is86?"BX = offset (hex)":kind==="fetch"?"PC (hex)":"DPTR (hex)";
    const a=NTE7.hex($("a").value,0xFFFF),x=NTE7.hex($("x").value,0xFF),s=NTE7.hex($("s").value,0xFFFF);
    if(isNaN(a)||(kind==="movc"&&isNaN(x))||(is86&&isNaN(s))){$("err").textContent="Nhập số hex 1–4 chữ số (A tối đa FF), ví dụ 2A51, 2A51H hoặc 0x2A51.";cur=null;draw();return}
    const tip=[["a",a],["x",kind==="movc"?x:NaN],["s",is86?s:NaN]].map(([i,v])=>isNaN(v)?"":NT.hexLit($(i).value,true).note).filter(Boolean)[0];
    $("err").textContent=tip?"Lưu ý: "+tip:"";cur=is86?Object.assign(NTE7.read86(s,a),{is86,seg:s,off:a}):Object.assign(NTE7.read51(kind,a,x),{is86});k=Math.min(k,3);draw()}
  function draw(){if(!cur){$("out").innerHTML="";$("st").textContent="";["prev","next","all"].forEach(i=>$(i).disabled=true);return}
    const ph=cur.phases,th=s=>`<th scope="col">${s}</th>`,row=(p,i)=>`<tr${i===k?' class="cur"':""}><td>${i+1}. ${p.t}</td>`+(cur.is86?`<td>${p.ALE}</td><td>${p.RD}</td><td>${p.MIO}</td><td>${p.A==null?"—":H(p.A,5)}</td><td>${p.D===null&&i<2?"—":H(p.D)}</td>`:`<td>${p.ALE}</td><td>${p.PSEN}</td><td>${p.RD}</td><td>${H(p.hi8)}</td><td>${H(p.lo8)}</td>`)+"</tr>";
    const head=cur.is86?`<tr>${th("Pha")}${th("ALE")}${th("RD")}${th("M/IO")}${th("A19–A0")}${th("D7–D0")}</tr>`:`<tr>${th("Pha")}${th("ALE")}${th("PSEN")}${th("RD")}${th("P2")}${th("P0")}</tr>`;
    const sum=cur.is86?`Địa chỉ vật lý = ${H(cur.seg,4)} × 16 + ${H(cur.off,4)} = <b>${H(cur.addr,5)}</b>${cur.wrap?" (vượt 20 bit, quay vòng về đầu bộ nhớ)":""}; M/IO = 1 (bộ nhớ); byte đọc được: <b>${H(cur.data)}</b>.`
      :`Địa chỉ ${H(cur.addr,4)} trong ${cur.space==="code"?"bộ nhớ chương trình":"RAM ngoài"}: P2 = <b>${H(cur.hi)}</b> (A15–A8), P0 lúc ALE = <b>${H(cur.lo)}</b> (A7–A0), tín hiệu đọc <b>${cur.strobe}</b>; byte đọc được: <b>${H(cur.data)}</b>.`;
    $("out").innerHTML=`<div class="tbl mt-fit"><table class="nt7-t"><thead>${head}</thead><tbody>${ph.slice(0,k+1).map(row).join("")}</tbody></table></div><p class="nt6-sum">${k===3?sum:"Mức 1 = không tích cực; ALE tích cực mức cao, PSEN và RD tích cực mức thấp."}</p>`;
    $("st").textContent=`Pha ${k+1}/4`;$("prev").disabled=k===0;$("next").disabled=$("all").disabled=k===3}
  $("prev").onclick=()=>{if(k>0){k--;draw()}};$("next").onclick=()=>{if(k<3){k++;draw()}};$("all").onclick=()=>{k=3;draw()};
  $("k").onchange=()=>{k=0;calc()};["a","x","s"].forEach(i=>$(i).addEventListener("input",()=>{k=0;calc()}));
  if(cfg.kind){$("k").value=cfg.kind;if(cfg.addr)$("a").value=cfg.addr}
  calc()}
