/* Bài 7 · CPU, bộ nhớ và bus (FND-007) — sinh bởi tools/author/nentang/m07.py, không sửa tay.
   Bảng bit tương tác, phòng mô phỏng từng bước và bài tập chấm tự động; phần chữ bài học ở lesson.html (nội dung bảo vệ). */
makeNtBusRead(document.getElementById("bus-l7"),{"id": "l7"});
makeMtLab(document.getElementById("lab-l7"),{id:"l7",scenarios:[{"label": "Ví dụ: Ba bus và dung lượng nhớ", "note": "2ⁿ ô với n đường địa chỉ; 65 536 khác 65 535.", "steps": [{"t": "CPU, bộ nhớ, ngoại vi nối bằng ba bus", "html": "<svg class=\"mt-svg\" viewBox=\"0 0 360 226\" role=\"img\" aria-label=\"CPU nối với bộ nhớ và ngoại vi bằng bus địa chỉ, bus dữ liệu và bus điều khiển\"><rect class=\"part\" x=\"8\" y=\"40\" width=\"78\" height=\"120\" rx=\"8\"/><text x=\"47\" y=\"96\" text-anchor=\"middle\">CPU<\/text><text x=\"47\" y=\"116\" text-anchor=\"middle\" class=\"sm muted\">PC, A…<\/text><path class=\"wire\" d=\"M86 62H282\"/><text x=\"94\" y=\"56\" class=\"sm\">Bus địa chỉ (CPU →)<\/text><path class=\"wire\" d=\"M176 62V178\"/><circle class=\"acc\" cx=\"176\" cy=\"62\" r=\"3\"/><path class=\"wire\" d=\"M282 62V178\"/><circle class=\"acc\" cx=\"282\" cy=\"62\" r=\"3\"/><path class=\"wire\" d=\"M86 100H304\"/><text x=\"94\" y=\"94\" class=\"sm\">Bus dữ liệu (↔)<\/text><path class=\"wire\" d=\"M198 100V178\"/><circle class=\"acc\" cx=\"198\" cy=\"100\" r=\"3\"/><path class=\"wire\" d=\"M304 100V178\"/><circle class=\"acc\" cx=\"304\" cy=\"100\" r=\"3\"/><path class=\"wire\" d=\"M86 138H326\"/><text x=\"94\" y=\"132\" class=\"sm\">Bus điều khiển (RD, WR…)<\/text><path class=\"wire\" d=\"M220 138V178\"/><circle class=\"acc\" cx=\"220\" cy=\"138\" r=\"3\"/><path class=\"wire\" d=\"M326 138V178\"/><circle class=\"acc\" cx=\"326\" cy=\"138\" r=\"3\"/><rect class=\"part\" x=\"150\" y=\"178\" width=\"96\" height=\"40\" rx=\"6\"/><text x=\"198\" y=\"203\" text-anchor=\"middle\" class=\"sm\">Bộ nhớ<\/text><rect class=\"part\" x=\"256\" y=\"178\" width=\"96\" height=\"40\" rx=\"6\"/><text x=\"304\" y=\"203\" text-anchor=\"middle\" class=\"sm\">Ngoại vi<\/text><\/svg>", "say": "<p>Bus địa chỉ do CPU đặt, chọn ô nào; bus dữ liệu chở byte theo hai chiều; bus điều khiển nói đọc hay ghi, lúc nào.<\/p>"}, {"t": "Bus địa chỉ 16 bit chọn được 65 536 ô", "html": "<p class=\"mt-calc\">2¹⁶ = <b>65 536<\/b> ô = 64 KiB · địa chỉ 0000H … FFFFH<\/p>", "ask": {"q": "Bus địa chỉ 20 bit (8086) chọn được bao nhiêu ô?", "o": ["1 048 576 (1 MiB)", "65 536", "20"], "a": 0}}, {"t": "2²⁰ = 1 048 576 ô; chip nhớ cần log₂(dung lượng) đường", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Dung lượng<\/th><th scope=\"col\">= 2ⁿ byte<\/th><th scope=\"col\">Số đường địa chỉ<\/th><\/tr><\/thead><tbody><tr><td>2 KiB<\/td><td>2¹¹<\/td><td class=\"new\">11<\/td><\/tr><tr><td>32 KiB<\/td><td>2¹⁵<\/td><td class=\"new\">15<\/td><\/tr><tr><td>64 KiB<\/td><td>2¹⁶<\/td><td>16<\/td><\/tr><tr><td>1 MiB<\/td><td>2²⁰<\/td><td>20<\/td><\/tr><\/tbody><\/table>", "say": "<p>65 535 (FFFFH) là địa chỉ <b>lớn nhất<\/b>, không phải số ô: có thêm ô 0000H.<\/p>"}]}, {"label": "Ví dụ: CPU nạp và chạy MOV A,#3CH", "note": "Opcode, toán hạng, PC tăng theo số byte.", "steps": [{"t": "Bộ nhớ chương trình từ 0000H; PC = 0000H", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Địa chỉ<\/th><th scope=\"col\">0000H<\/th><th scope=\"col\">0001H<\/th><th scope=\"col\">0002H<\/th><th scope=\"col\">0003H<\/th><th scope=\"col\">0004H<\/th><\/tr><\/thead><tbody><tr><td>Byte<\/td><td class=\"new\">74H<\/td><td>3CH<\/td><td>90H<\/td><td>01H<\/td><td>00H<\/td><\/tr><\/tbody><\/table>", "say": "<p>Sau reset PC = 0000H. Năm byte này là <code>MOV A,#3CH<\/code> (74H 3CH) và <code>MOV DPTR,#0100H<\/code> (90H 01H 00H).<\/p>"}, {"t": "Nạp opcode 74H, PC → 0001H, giải mã", "html": "<p class=\"mt-calc\">đọc ô PC = 0000H → <b>74H<\/b> · PC = 0001H · 74H = MOV A,#data: cần thêm 1 byte<\/p>", "say": "<p>Opcode cho CPU biết lệnh gì và còn bao nhiêu byte toán hạng.<\/p>"}, {"t": "Nạp toán hạng 3CH, PC → 0002H", "html": "<p class=\"mt-calc\">đọc ô 0001H → <b>3CH<\/b> (dữ liệu tức thời) · PC = <b>0002H<\/b><\/p>", "ask": {"q": "Nạp xong MOV A,#3CH, PC bằng bao nhiêu?", "o": ["0001H", "0002H", "0000H"], "a": 1}}, {"t": "Thực thi: A = 3CH (s51: PC = 0002H)", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Thanh ghi<\/th><th scope=\"col\">Trước<\/th><th scope=\"col\">Sau<\/th><\/tr><\/thead><tbody><tr><td>PC<\/td><td>0000H<\/td><td class=\"new\">0002H<\/td><\/tr><tr><td>A<\/td><td>00H<\/td><td class=\"new\">3CH<\/td><\/tr><\/tbody><\/table>", "say": "<p>ucsim s51 cho đúng PC = 0002H, A = 3CH, 12 chu kỳ dao động (1 chu kỳ máy). Byte 3CH là dữ liệu nằm ngay trong lệnh, không phải địa chỉ.<\/p>"}]}, {"label": "Ví dụ: MOVX đọc RAM ngoài 0100H", "note": "P\u0032, P\u0030, ALE, RD qua bốn pha; A = 5AH.", "steps": [{"t": "DPTR = 0100H rồi MOVX A,@DPTR (E0H)", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Lệnh A51<\/th><th scope=\"col\">Mã máy<\/th><th scope=\"col\">Chu kỳ máy<\/th><\/tr><\/thead><tbody><tr><td>MOV DPTR,#0100H<\/td><td>90H 01H 00H<\/td><td>2<\/td><\/tr><tr><td>MOVX A,@DPTR<\/td><td>E0H<\/td><td>2<\/td><\/tr><\/tbody><\/table>", "say": "<p>Giả định: RAM ngoài ô 0100H chứa 5AH. MOVX dùng cổng P\u0032, P\u0030 và chân RD (P\u0033.7) làm bus ngoài.<\/p>"}, {"t": "Pha 1: P\u0032 = 01H, P\u0030 = 00H, ALE = 1", "html": "<div class=\"nt2-wave\" role=\"img\" aria-label=\"Thứ tự sự kiện khi 8051 đọc RAM ngoài ở địa chỉ 0100H. ALE: 1 0 0 0; PSEN: 1 1 1 1; RD: 1 1 0 1; P\u0032: 01H 01H 01H 01H; P\u0030: 00H 00H 5AH 5AH; Chốt: 00H 00H 00H 00H\"><b>ALE<\/b><div style=\"--n:4\"><i class=\"h c\"><\/i><i class=\"e\"><\/i><i class=\"\"><\/i><i class=\"\"><\/i><\/div><b>PSEN<\/b><div style=\"--n:4\"><i class=\"h\"><\/i><i class=\"h\"><\/i><i class=\"h\"><\/i><i class=\"h\"><\/i><\/div><b>RD<\/b><div style=\"--n:4\"><i class=\"h\"><\/i><i class=\"h\"><\/i><i class=\"e\"><\/i><i class=\"h e\"><\/i><\/div><b>P\u0032<\/b><div style=\"--n:4\"><i class=\"v\">01H<\/i><i class=\"v\">01H<\/i><i class=\"v\">01H<\/i><i class=\"v\">01H<\/i><\/div><b>P\u0030<\/b><div style=\"--n:4\"><i class=\"v\">00H<\/i><i class=\"v\">00H<\/i><i class=\"v\">5AH<\/i><i class=\"v\">5AH<\/i><\/div><b>Chốt<\/b><div style=\"--n:4\"><i class=\"v\">00H<\/i><i class=\"v\">00H<\/i><i class=\"v\">00H<\/i><i class=\"v\">00H<\/i><\/div><b><\/b><div class=\"nt2-ax\" style=\"--n:4\"><i>pha 1<\/i><i>pha 2<\/i><i>pha 3<\/i><i>pha 4<\/i><\/div><\/div>", "ask": {"q": "Trong pha 1, P\u0030 mang gì?", "o": ["01H: 8 bit cao của địa chỉ", "5AH: dữ liệu", "00H: 8 bit thấp của địa chỉ"], "a": 2}}, {"t": "Pha 2: ALE xuống, mạch chốt giữ 00H", "html": "<div class=\"nt2-wave\" role=\"img\" aria-label=\"Thứ tự sự kiện khi 8051 đọc RAM ngoài ở địa chỉ 0100H. ALE: 1 0 0 0; PSEN: 1 1 1 1; RD: 1 1 0 1; P\u0032: 01H 01H 01H 01H; P\u0030: 00H 00H 5AH 5AH; Chốt: 00H 00H 00H 00H\"><b>ALE<\/b><div style=\"--n:4\"><i class=\"h\"><\/i><i class=\"e c\"><\/i><i class=\"\"><\/i><i class=\"\"><\/i><\/div><b>PSEN<\/b><div style=\"--n:4\"><i class=\"h\"><\/i><i class=\"h\"><\/i><i class=\"h\"><\/i><i class=\"h\"><\/i><\/div><b>RD<\/b><div style=\"--n:4\"><i class=\"h\"><\/i><i class=\"h\"><\/i><i class=\"e\"><\/i><i class=\"h e\"><\/i><\/div><b>P\u0032<\/b><div style=\"--n:4\"><i class=\"v\">01H<\/i><i class=\"v\">01H<\/i><i class=\"v\">01H<\/i><i class=\"v\">01H<\/i><\/div><b>P\u0030<\/b><div style=\"--n:4\"><i class=\"v\">00H<\/i><i class=\"v\">00H<\/i><i class=\"v\">5AH<\/i><i class=\"v\">5AH<\/i><\/div><b>Chốt<\/b><div style=\"--n:4\"><i class=\"v\">00H<\/i><i class=\"v\">00H<\/i><i class=\"v\">00H<\/i><i class=\"v\">00H<\/i><\/div><b><\/b><div class=\"nt2-ax\" style=\"--n:4\"><i>pha 1<\/i><i>pha 2<\/i><i>pha 3<\/i><i>pha 4<\/i><\/div><\/div>", "say": "<p>Từ đây bộ nhớ lấy A7–A0 từ mạch chốt, nên P\u0030 được rảnh để chở dữ liệu.<\/p>"}, {"t": "Pha 3–4: RD xuống, RAM đặt 5AH lên P\u0030; A = 5AH", "html": "<div class=\"nt2-wave\" role=\"img\" aria-label=\"Thứ tự sự kiện khi 8051 đọc RAM ngoài ở địa chỉ 0100H. ALE: 1 0 0 0; PSEN: 1 1 1 1; RD: 1 1 0 1; P\u0032: 01H 01H 01H 01H; P\u0030: 00H 00H 5AH 5AH; Chốt: 00H 00H 00H 00H\"><b>ALE<\/b><div style=\"--n:4\"><i class=\"h\"><\/i><i class=\"e\"><\/i><i class=\"c\"><\/i><i class=\"\"><\/i><\/div><b>PSEN<\/b><div style=\"--n:4\"><i class=\"h\"><\/i><i class=\"h\"><\/i><i class=\"h c\"><\/i><i class=\"h\"><\/i><\/div><b>RD<\/b><div style=\"--n:4\"><i class=\"h\"><\/i><i class=\"h\"><\/i><i class=\"e c\"><\/i><i class=\"h e\"><\/i><\/div><b>P\u0032<\/b><div style=\"--n:4\"><i class=\"v\">01H<\/i><i class=\"v\">01H<\/i><i class=\"v\">01H<\/i><i class=\"v\">01H<\/i><\/div><b>P\u0030<\/b><div style=\"--n:4\"><i class=\"v\">00H<\/i><i class=\"v\">00H<\/i><i class=\"v\">5AH<\/i><i class=\"v\">5AH<\/i><\/div><b>Chốt<\/b><div style=\"--n:4\"><i class=\"v\">00H<\/i><i class=\"v\">00H<\/i><i class=\"v\">00H<\/i><i class=\"v\">00H<\/i><\/div><b><\/b><div class=\"nt2-ax\" style=\"--n:4\"><i>pha 1<\/i><i>pha 2<\/i><i>pha 3<\/i><i>pha 4<\/i><\/div><\/div><p class=\"mt-calc\">A = <b>5AH<\/b> · s51: A = 5AH sau 24 chu kỳ dao động (2 chu kỳ máy)<\/p>", "say": "<p>PSEN giữ 1 suốt lần đọc này: RAM ngoài dùng RD, không dùng PSEN.<\/p>"}]}, {"label": "Bẫy: MOVC và MOVX cùng địa chỉ", "note": "Bộ nhớ chương trình và RAM ngoài là hai không gian.", "steps": [{"t": "Hai vùng nhớ, cùng địa chỉ 0100H", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Vùng<\/th><th scope=\"col\">Ô 0100H (giả định)<\/th><th scope=\"col\">Đọc bằng<\/th><\/tr><\/thead><tbody><tr><td>Bộ nhớ chương trình<\/td><td>3FH<\/td><td>MOVC, tín hiệu PSEN<\/td><\/tr><tr><td>RAM ngoài<\/td><td>5AH<\/td><td>MOVX, tín hiệu RD<\/td><\/tr><\/tbody><\/table>", "say": "<p>8051 có không gian chương trình và không gian dữ liệu ngoài tách riêng (kiểu Harvard).<\/p>"}, {"t": "CLR A rồi MOVC A,@A+DPTR (93H), DPTR = 0100H", "html": "<p class=\"mt-calc\">địa chỉ = A + DPTR = 00H + 0100H = 0100H<\/p>", "ask": {"q": "Sau MOVC A,@A+DPTR, A bằng bao nhiêu?", "o": ["3FH", "5AH", "00H"], "a": 0}}, {"t": "PSEN xuống thay vì RD: A = 3FH", "html": "<div class=\"nt2-wave\" role=\"img\" aria-label=\"Thứ tự sự kiện khi 8051 đọc bộ nhớ chương trình ở địa chỉ 0100H. ALE: 1 0 0 0; PSEN: 1 1 0 1; RD: 1 1 1 1; P\u0032: 01H 01H 01H 01H; P\u0030: 00H 00H 3FH 3FH; Chốt: 00H 00H 00H 00H\"><b>ALE<\/b><div style=\"--n:4\"><i class=\"h\"><\/i><i class=\"e\"><\/i><i class=\"c\"><\/i><i class=\"\"><\/i><\/div><b>PSEN<\/b><div style=\"--n:4\"><i class=\"h\"><\/i><i class=\"h\"><\/i><i class=\"e c\"><\/i><i class=\"h e\"><\/i><\/div><b>RD<\/b><div style=\"--n:4\"><i class=\"h\"><\/i><i class=\"h\"><\/i><i class=\"h c\"><\/i><i class=\"h\"><\/i><\/div><b>P\u0032<\/b><div style=\"--n:4\"><i class=\"v\">01H<\/i><i class=\"v\">01H<\/i><i class=\"v\">01H<\/i><i class=\"v\">01H<\/i><\/div><b>P\u0030<\/b><div style=\"--n:4\"><i class=\"v\">00H<\/i><i class=\"v\">00H<\/i><i class=\"v\">3FH<\/i><i class=\"v\">3FH<\/i><\/div><b>Chốt<\/b><div style=\"--n:4\"><i class=\"v\">00H<\/i><i class=\"v\">00H<\/i><i class=\"v\">00H<\/i><i class=\"v\">00H<\/i><\/div><b><\/b><div class=\"nt2-ax\" style=\"--n:4\"><i>pha 1<\/i><i>pha 2<\/i><i>pha 3<\/i><i>pha 4<\/i><\/div><\/div><p class=\"mt-calc\">A = <b>3FH<\/b> (s51 xác nhận) ≠ 5AH của MOVX<\/p>", "say": "<p>Cùng con số 0100H nhưng là hai ô khác nhau. Nhầm MOVC với MOVX là đọc nhầm bảng.<\/p>"}]}, {"label": "Lỗi: Bỏ mạch chốt địa chỉ", "note": "P\u0030 đổi sang dữ liệu, bộ nhớ mất A7–A0.", "steps": [{"t": "Có mạch chốt: bộ nhớ thấy 2A51H suốt lần đọc", "html": "<div class=\"nt2-wave\" role=\"img\" aria-label=\"Thứ tự sự kiện khi 8051 đọc RAM ngoài ở địa chỉ 2A51H. ALE: 1 0 0 0; PSEN: 1 1 1 1; RD: 1 1 0 1; P\u0032: 2AH 2AH 2AH 2AH; P\u0030: 51H 51H C3H C3H; Chốt: 51H 51H 51H 51H\"><b>ALE<\/b><div style=\"--n:4\"><i class=\"h\"><\/i><i class=\"e\"><\/i><i class=\"c\"><\/i><i class=\"\"><\/i><\/div><b>PSEN<\/b><div style=\"--n:4\"><i class=\"h\"><\/i><i class=\"h\"><\/i><i class=\"h c\"><\/i><i class=\"h\"><\/i><\/div><b>RD<\/b><div style=\"--n:4\"><i class=\"h\"><\/i><i class=\"h\"><\/i><i class=\"e c\"><\/i><i class=\"h e\"><\/i><\/div><b>P\u0032<\/b><div style=\"--n:4\"><i class=\"v\">2AH<\/i><i class=\"v\">2AH<\/i><i class=\"v\">2AH<\/i><i class=\"v\">2AH<\/i><\/div><b>P\u0030<\/b><div style=\"--n:4\"><i class=\"v\">51H<\/i><i class=\"v\">51H<\/i><i class=\"v\">C3H<\/i><i class=\"v\">C3H<\/i><\/div><b>Chốt<\/b><div style=\"--n:4\"><i class=\"v\">51H<\/i><i class=\"v\">51H<\/i><i class=\"v\">51H<\/i><i class=\"v\">51H<\/i><\/div><b><\/b><div class=\"nt2-ax\" style=\"--n:4\"><i>pha 1<\/i><i>pha 2<\/i><i>pha 3<\/i><i>pha 4<\/i><\/div><\/div>", "say": "<p>DPTR = 2A51H; RAM ngoài ô 2A51H chứa C3H (giả định). Hàng “Chốt” là đầu ra của mạch chốt 8 bit nối vào A7–A0 của bộ nhớ.<\/p>"}, {"t": "Bỏ mạch chốt, nối thẳng P\u0030 vào A7–A0", "html": "<div class=\"nt2-wave\" role=\"img\" aria-label=\"Thứ tự sự kiện khi 8051 đọc RAM ngoài ở địa chỉ 2A51H. ALE: 1 0 0 0; PSEN: 1 1 1 1; RD: 1 1 0 1; P\u0032: 2AH 2AH 2AH 2AH; P\u0030: 51H 51H C3H C3H; A7–A0: 51H   \"><b>ALE<\/b><div style=\"--n:4\"><i class=\"h\"><\/i><i class=\"e\"><\/i><i class=\"c\"><\/i><i class=\"\"><\/i><\/div><b>PSEN<\/b><div style=\"--n:4\"><i class=\"h\"><\/i><i class=\"h\"><\/i><i class=\"h c\"><\/i><i class=\"h\"><\/i><\/div><b>RD<\/b><div style=\"--n:4\"><i class=\"h\"><\/i><i class=\"h\"><\/i><i class=\"e c\"><\/i><i class=\"h e\"><\/i><\/div><b>P\u0032<\/b><div style=\"--n:4\"><i class=\"v\">2AH<\/i><i class=\"v\">2AH<\/i><i class=\"v\">2AH<\/i><i class=\"v\">2AH<\/i><\/div><b>P\u0030<\/b><div style=\"--n:4\"><i class=\"v\">51H<\/i><i class=\"v\">51H<\/i><i class=\"v\">C3H<\/i><i class=\"v\">C3H<\/i><\/div><b>A7–A0<\/b><div style=\"--n:4\"><i class=\"v\">51H<\/i><i class=\"x\"><\/i><i class=\"x\"><\/i><i class=\"x\"><\/i><\/div><b><\/b><div class=\"nt2-ax\" style=\"--n:4\"><i>pha 1<\/i><i>pha 2<\/i><i>pha 3<\/i><i>pha 4<\/i><\/div><\/div>", "ask": {"q": "Không có mạch chốt, lúc RD xuống bộ nhớ thấy địa chỉ nào?", "o": ["Vẫn 2A51H", "Không xác định: A7–A0 lúc đó là thứ đang có trên P\u0030", "0000H"], "a": 1}}, {"t": "Sửa: mạch chốt 8 bit, chân cho phép nối ALE", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Chân 8051<\/th><th scope=\"col\">Nối tới<\/th><\/tr><\/thead><tbody><tr><td>P\u0030 (AD7–AD0)<\/td><td>đầu vào mạch chốt và D7–D0 của bộ nhớ<\/td><\/tr><tr><td>ALE<\/td><td class=\"new\">chân cho phép chốt<\/td><\/tr><tr><td>P\u0032 (A15–A8)<\/td><td>A15–A8 của bộ nhớ (không cần chốt)<\/td><\/tr><tr><td>RD, WR<\/td><td>OE, WE của RAM<\/td><\/tr><tr><td>PSEN<\/td><td>OE của ROM/flash ngoài<\/td><\/tr><\/tbody><\/table>", "say": "<p>P\u0030 làm hai việc trong một lần đọc (dồn kênh): trước chở A7–A0, sau chở dữ liệu. Chọn IC chốt cụ thể và kiểm thời gian trong datasheet của nó.<\/p>"}]}, {"label": "Bẫy: Địa chỉ 90H là SFR P\u0031", "note": "Địa chỉ trực tiếp 80H–FFH không phải RAM ở 8051 gốc.", "steps": [{"t": "Địa chỉ trực tiếp: 00H–7FH là RAM, 80H–FFH là SFR", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Vùng (8051 gốc)<\/th><th scope=\"col\">Địa chỉ<\/th><th scope=\"col\">Lệnh truy cập<\/th><th scope=\"col\">Tín hiệu<\/th><\/tr><\/thead><tbody><tr><td>Bộ nhớ chương trình<\/td><td>0000H–FFFFH<\/td><td>nạp lệnh, MOVC<\/td><td>PSEN (khi đọc ngoài)<\/td><\/tr><tr><td>RAM trong<\/td><td>00H–7FH<\/td><td>MOV trực tiếp, MOV @R0/@R1<\/td><td>trong chip<\/td><\/tr><tr><td>SFR (P\u0030–P\u0033, A, B, SP…)<\/td><td>80H–FFH<\/td><td>MOV trực tiếp<\/td><td>trong chip<\/td><\/tr><tr><td>RAM ngoài (XDATA)<\/td><td>0000H–FFFFH<\/td><td>MOVX<\/td><td>RD, WR<\/td><\/tr><\/tbody><\/table>", "say": "<p>8051 gốc có 128 byte RAM trong. Địa chỉ 90H dùng trực tiếp là thanh ghi cổng P\u0031.<\/p>"}, {"t": "MOV P\u0031,#0A5H rồi MOV A,90H (E5H 90H)", "html": "<p class=\"mt-calc\">90H ≥ 80H, địa chỉ trực tiếp → SFR P\u0031, không phải RAM<\/p>", "ask": {"q": "Sau MOV A,90H, A bằng bao nhiêu (chân P\u0031 không nối gì)?", "o": ["00H: ô RAM 90H còn trống", "Không đọc được", "A5H: đọc SFR P\u0031"], "a": 2}}, {"t": "A = A5H; RAM trong 30H đọc qua @R0 = 77H", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Lệnh<\/th><th scope=\"col\">Mã máy<\/th><th scope=\"col\">Vùng<\/th><th scope=\"col\">A sau lệnh (s51)<\/th><\/tr><\/thead><tbody><tr><td>MOV A,90H<\/td><td>E5H 90H<\/td><td>SFR P\u0031<\/td><td class=\"new\">A5H<\/td><\/tr><tr><td>MOV A,30H<\/td><td>E5H 30H<\/td><td>RAM trong<\/td><td>—<\/td><\/tr><tr><td>MOV A,@R0 (R0 = 30H)<\/td><td>E6H<\/td><td>RAM trong<\/td><td class=\"new\">77H<\/td><\/tr><\/tbody><\/table>", "say": "<p>MOV A,P\u0031 đọc mức trên chân; chân không nối gì nên bằng giá trị đã ghi. Với 8051 gốc, @R0 chỉ tới RAM trong 00H–7FH, không tới SFR.<\/p>"}]}, {"label": "Ví dụ: 8086 đọc ô nhớ qua DS:BX", "note": "Segment × 16 + offset; T1–T4; M/IO = 1.", "steps": [{"t": "DS = 1234H, BX = 0010H", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Lệnh MASM<\/th><th scope=\"col\">Mã máy<\/th><\/tr><\/thead><tbody><tr><td>MOV AX,1234h<\/td><td>B8H 34H 12H<\/td><\/tr><tr><td>MOV DS,AX<\/td><td>8EH D8H<\/td><\/tr><tr><td>MOV BX,0010h<\/td><td>BBH 10H 00H<\/td><\/tr><tr><td>MOV AL,[BX]<\/td><td>8AH 07H<\/td><\/tr><\/tbody><\/table>", "say": "<p>8086 không nạp hằng số thẳng vào DS được, nên đi qua AX. Ô vật lý 12350H chứa 7EH (giả định).<\/p>"}, {"t": "Địa chỉ vật lý = DS × 16 + BX", "html": "<p class=\"mt-calc\">1234H × 16 = 12340H<\/p>", "ask": {"q": "Địa chỉ vật lý của DS:BX = 1234H:0010H?", "o": ["12350H", "1244H", "12340H"], "a": 0}}, {"t": "12340H + 0010H = 12350H; đọc ở T1–T4", "html": "<div class=\"nt2-wave\" role=\"img\" aria-label=\"Thứ tự sự kiện khi 8086 đọc một byte ở địa chỉ vật lý 12350H. ALE: 1 0 0 0; RD: 1 0 0 1; M/IO: 1 1 1 1; AD: 12350H  7EH 7EH\"><b>ALE<\/b><div style=\"--n:4\"><i class=\"h\"><\/i><i class=\"e\"><\/i><i class=\"c\"><\/i><i class=\"\"><\/i><\/div><b>RD<\/b><div style=\"--n:4\"><i class=\"h\"><\/i><i class=\"e\"><\/i><i class=\"\"><\/i><i class=\"h e\"><\/i><\/div><b>M/IO<\/b><div style=\"--n:4\"><i class=\"h\"><\/i><i class=\"h\"><\/i><i class=\"h\"><\/i><i class=\"h\"><\/i><\/div><b>AD<\/b><div style=\"--n:4\"><i class=\"v\">12350H<\/i><i class=\"x\"><\/i><i class=\"v\">7EH<\/i><i class=\"v\">7EH<\/i><\/div><b><\/b><div class=\"nt2-ax\" style=\"--n:4\"><i>T1<\/i><i>T2<\/i><i>T3<\/i><i>T4<\/i><\/div><\/div><p class=\"mt-calc\">AL = <b>7EH<\/b><\/p>", "say": "<p>Nhân 16 là dịch trái 4 bit (thêm một chữ số 0 hex). 1244H là lỗi cộng thẳng segment với offset. M/IO = 1: truy cập bộ nhớ.<\/p>"}, {"t": "Một ô, nhiều cách viết segment:offset", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Segment:offset<\/th><th scope=\"col\">Địa chỉ vật lý<\/th><\/tr><\/thead><tbody><tr><td>1234H:0010H<\/td><td>12350H<\/td><\/tr><tr><td>1235H:0000H<\/td><td>12350H<\/td><\/tr><tr><td>1000H:2350H<\/td><td>12350H<\/td><\/tr><\/tbody><\/table>"}]}, {"label": "Bẫy: IN AL,60h không phải ô nhớ 60h", "note": "Không gian I/O riêng của 8086; 8051 ánh xạ bộ nhớ.", "steps": [{"t": "IN AL,60h (E4H 60H): M/IO = 0", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Lệnh<\/th><th scope=\"col\">Mã máy<\/th><th scope=\"col\">Không gian<\/th><th scope=\"col\">M/IO<\/th><\/tr><\/thead><tbody><tr><td>IN AL,60h<\/td><td>E4H 60H<\/td><td>I/O, cổng 60h<\/td><td>0<\/td><\/tr><tr><td>MOV AL,[BX]<\/td><td>8AH 07H<\/td><td>bộ nhớ<\/td><td>1<\/td><\/tr><\/tbody><\/table>", "say": "<p>8086 có không gian I/O riêng: lệnh IN/OUT đặt M/IO = 0 nên chip nhớ không trả lời, chỉ chip cổng được giải mã ở địa chỉ đó trả lời.<\/p>"}, {"t": "DS = 0000H, BX = 0060h: MOV AL,[BX] đọc 00060H", "html": "<p class=\"mt-calc\">0000H × 16 + 0060H = 00060H (ô nhớ)<\/p>", "ask": {"q": "IN AL,60h và MOV AL,[BX] (DS = 0, BX = 0060h) có đọc cùng một chỗ không?", "o": ["Không: cổng I/O 60h khác ô nhớ 00060H", "Có: cùng địa chỉ 60h"], "a": 0}}, {"t": "8051 không có không gian I/O riêng", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Cách nối ngoại vi<\/th><th scope=\"col\">Ví dụ<\/th><th scope=\"col\">Lệnh<\/th><\/tr><\/thead><tbody><tr><td>Thanh ghi SFR trong chip<\/td><td>P\u0031 ở 90H<\/td><td>MOV<\/td><\/tr><tr><td>Ánh xạ vào RAM ngoài<\/td><td>chip cổng ở 8000H (giả định)<\/td><td>MOVX<\/td><\/tr><tr><td>Không gian I/O riêng (8086)<\/td><td>cổng 60h<\/td><td>IN, OUT<\/td><\/tr><\/tbody><\/table>", "say": "<p>Ngoại vi nằm chung không gian với bộ nhớ gọi là ánh xạ bộ nhớ; có không gian riêng gọi là ánh xạ cổng.<\/p>"}]}]});
makeMtEx(document.getElementById("ex-l7"),"l7",[{"kind": "num", "t": "Bus và dung lượng nhớ", "d": "<p>Trả lời bằng số thập phân. Một địa chỉ ứng với một byte. 8051 kiểu gốc, thạch anh 12 MHz (1 chu kỳ máy = 1 µs).<\/p>", "items": [{"q": "Bus địa chỉ 16 bit đánh địa chỉ được bao nhiêu byte", "a": 65536, "tol": 0, "unit": "byte"}, {"q": "Bus địa chỉ 20 bit (8086) đánh địa chỉ được bao nhiêu byte", "a": 1048576, "tol": 0, "unit": "byte"}, {"q": "Chip nhớ 2 KiB cần bao nhiêu đường địa chỉ", "a": 11, "tol": 0, "unit": "đường"}, {"q": "Chip nhớ 32 KiB cần bao nhiêu đường địa chỉ", "a": 15, "tol": 0, "unit": "đường"}, {"q": "Bus dữ liệu 8 bit: cần mấy lần đọc để lấy một word 16 bit", "a": 2, "tol": 0, "unit": "lần"}, {"q": "MOVX A,@DPTR mất 2 chu kỳ máy. Thời gian ở 12 MHz", "a": 2, "tol": 0, "unit": "µs"}], "hints": ["n đường địa chỉ chọn được 2ⁿ ô nhớ khác nhau.", "2 KiB = 2 × 1024 = 2¹¹ byte; 32 KiB = 2¹⁵ byte.", "2¹⁶ = 65 536, 2²⁰ = 1 048 576. Một word 16 bit là 2 byte."], "why": "2¹⁶ = 65 536; 2²⁰ = 1 048 576; 2 KiB = 2¹¹ → 11 đường; 32 KiB = 2¹⁵ → 15 đường; bus 8 bit chở 1 byte mỗi lần nên một word cần 2 lần; 2 chu kỳ máy × 1 µs = 2 µs."}, {"kind": "base", "t": "Theo dõi một lần đọc", "d": "<p>Trả lời theo hệ ghi sau mỗi ô. Hex có thể viết 2A, 2AH hoặc 0x2A.<\/p>", "items": [{"q": "MOVX A,@DPTR với DPTR = 2A51H: giá trị trên P\u0032 trong lúc đọc", "f": "hex", "a": 42}, {"q": "Cũng lệnh đó: giá trị trên P\u0030 lúc ALE chốt địa chỉ", "f": "hex", "a": 81}, {"q": "MOVC A,@A+DPTR với A = 05H, DPTR = 0100H: địa chỉ bộ nhớ chương trình được đọc", "f": "hex", "a": 261}, {"q": "MOV A,#3CH nằm ở 0000H. Sau khi CPU nạp xong lệnh này, PC bằng", "f": "hex", "a": 2}, {"q": "8086, DS = 1234H. Offset để đọc địa chỉ vật lý 12350H", "f": "hex", "a": 16}, {"q": "8086, offset 0000H. Segment để đọc địa chỉ vật lý B8000H", "f": "hex", "a": 47104}, {"q": "8086: byte đầu (opcode) của MOV AL,[BX]", "f": "hex", "a": 138}], "hints": ["P\u0032 mang 8 bit cao của địa chỉ (A15–A8), P\u0030 lúc ALE mang 8 bit thấp (A7–A0).", "MOVC đọc ô (A + DPTR). PC tăng thêm đúng số byte của lệnh vừa nạp.", "Địa chỉ vật lý = segment × 16 + offset: 12340H + offset = 12350H; segment × 16 = B8000H. MOV AL,[BX] dịch thành 8AH 07H."], "why": "P\u0032 = 2AH, P\u0030 = 51H; 0100H + 05H = 0105H; MOV A,#3CH dài 2 byte nên PC = 0002H; 12350H − 12340H = 0010H; B8000H ÷ 16 = B800H; MOV AL,[BX] = 8AH 07H (NASM)."}, {"kind": "pick", "t": "Lệnh nào đụng tới vùng nào", "d": "<p>8051 kiểu gốc (128 byte RAM trong, SFR ở 80H–FFH khi dùng địa chỉ trực tiếp) và 8086. Chọn vùng mà mỗi thao tác đọc hoặc ghi.<\/p>", "cats": ["Bộ nhớ chương trình", "RAM trong", "SFR / cổng", "RAM ngoài", "Không gian I/O của 8086"], "items": [{"q": "MOVC A,@A+DPTR", "a": 0}, {"q": "MOVX A,@DPTR", "a": 3}, {"q": "MOV A,30H", "a": 1}, {"q": "MOV A,90H", "a": 2}, {"q": "CPU nạp opcode tại địa chỉ PC", "a": 0}, {"q": "IN AL,60h (8086)", "a": 4}, {"q": "MOVX @DPTR,A", "a": 3}, {"q": "MOV A,@R0 với R0 = 30H", "a": 1}], "hints": ["8051 có các không gian nhớ tách riêng; lệnh quyết định vùng nào: MOVC → chương trình, MOVX → RAM ngoài.", "Địa chỉ trực tiếp 00H–7FH là RAM trong, 80H–FFH là SFR (P\u0031 ở 90H).", "8086 dùng IN/OUT cho không gian I/O riêng, MOV cho bộ nhớ."], "why": "MOVC và nạp lệnh dùng bộ nhớ chương trình (PSEN); MOVX đọc/ghi RAM ngoài (RD/WR); 30H trực tiếp hoặc qua @R0 là RAM trong; 90H trực tiếp là SFR P\u0031; IN là không gian I/O của 8086."}]);

makeQuiz("quiz7","score7",[{"q": "Bus địa chỉ 16 bit đánh địa chỉ được bao nhiêu byte?", "o": ["65 535 byte", "16 byte", "65 536 byte (64 KiB)", "1 048 576 byte"], "a": 2, "e": "16 đường địa chỉ tạo 2¹⁶ = 65 536 tổ hợp, từ 0000H tới FFFFH. 65 535 là địa chỉ lớn nhất, không phải số ô; 1 048 576 là của bus 20 bit."}, {"q": "8051 chạy MOVX A,@DPTR với DPTR = 1234H và dùng RAM ngoài. Lúc ALE chốt địa chỉ, P2 và P0 mang giá trị gì?", "o": ["P2 = 34H, P0 = 12H", "P2 = 12H, P0 = 34H", "P0 = 1234H", "P2 = 12H, P0 = byte dữ liệu đọc được"], "a": 1, "e": "P2 xuất 8 bit cao A15–A8, P0 xuất 8 bit thấp A7–A0 trước, rồi mới đổi sang chở dữ liệu. P0 chỉ có 8 bit nên không chứa được 1234H; dữ liệu chỉ xuất hiện trên P0 sau khi RD xuống."}, {"q": "Cùng DPTR = 0100H (A = 00H). MOVC A,@A+DPTR và MOVX A,@DPTR khác nhau thế nào?", "o": ["Giống nhau, chỉ khác số chu kỳ máy", "MOVC ghi vào ô 0100H, MOVX đọc ô 0100H", "MOVC đọc bộ nhớ chương trình (PSEN), MOVX đọc RAM ngoài (RD)", "MOVX đọc RAM trong ở ô 0100H"], "a": 2, "e": "8051 có không gian nhớ chương trình và RAM ngoài tách riêng: cùng địa chỉ 0100H là hai ô khác nhau. Trong ví dụ đối chiếu bằng s51, MOVC cho 3FH, MOVX cho 5AH. Cả hai đều 2 chu kỳ máy; RAM trong chỉ có 8 bit địa chỉ."}, {"q": "8086 chạy MOV AL,[BX] với DS = 2000H, BX = 0100H. Địa chỉ vật lý được đọc là bao nhiêu?", "o": ["20100H", "02100H", "21000H", "00100H"], "a": 0, "e": "Địa chỉ vật lý = DS × 16 + offset = 20000H + 0100H = 20100H. 02100H là cộng thẳng 2000H + 0100H; 21000H là dịch nhầm offset; 00100H là quên segment."}, {"q": "Vì sao 8051 cần mạch chốt địa chỉ bên ngoài khi dùng bộ nhớ ngoài?", "o": ["Để tăng dòng cho các chân P0", "Vì P2 không đủ 8 bit địa chỉ cao", "Để chống dội cho tín hiệu PSEN", "P0 mang A0–A7 rồi đổi sang chở dữ liệu trong cùng lần đọc; mạch chốt giữ A0–A7 khi ALE xuống"], "a": 3, "e": "P0 dồn kênh địa chỉ thấp và dữ liệu. Nếu không chốt, khi P0 đổi sang dữ liệu thì bộ nhớ thấy A0–A7 thay đổi và trả sai ô. P2 đủ 8 bit cho A15–A8."}]);

